int fib(int n){
    if(n < 2) return n;
    return fib(n-1) + fib(n-2);
}

int dp[1005];
int fib(int n){
    if(n < 2) return n;
    if(dp[n] != -1) return dp[n];    // already answered
    dp[n] = fib(n-1) + fib(n-2);     // answer it once
    return dp[n];
}
